-- Final platform columns for step 3.
-- Review and run this yourself. Do not apply it from the app.
-- Do not edit this file in a later phase. Do not edit 0033. Do not apply 0022.
--
-- Writes go through the service role, which bypasses RLS.
-- New tables are select-only for the owner and for a reseller, matching 0025.

-- ---------------------------------------------------------------------------
-- products.reorder_point
-- Null means the shared REORDER_POINT constant (10) in application code.
-- ---------------------------------------------------------------------------

alter table products
  add column if not exists reorder_point integer;

alter table products
  drop constraint if exists products_reorder_point_chk;
alter table products
  add constraint products_reorder_point_chk
  check (reorder_point is null or reorder_point >= 0);

-- Inventory attention list.
-- Query: select id, reorder_point, stock_count from products
--        where status <> 'archived' and stock_unlimited = false
-- Why: the inventory screen compares stock_count with each product's own point.
create index if not exists idx_products_reorder_point
  on products (reorder_point, stock_count)
  where reorder_point is not null and stock_unlimited = false;

-- ---------------------------------------------------------------------------
-- supplier_balance_snapshots
-- One row each time a supplier balance is checked or synced.
-- ---------------------------------------------------------------------------

create table if not exists supplier_balance_snapshots (
  id uuid primary key default gen_random_uuid(),
  supplier_id uuid not null references suppliers(id) on delete cascade,
  balance_usdt numeric not null,
  checked_at timestamptz not null default now()
);

-- Supplier health balance chart.
-- Query: select balance_usdt, checked_at from supplier_balance_snapshots
--        where supplier_id = $1 order by checked_at
-- Why: the health card plots one supplier's balances in time order.
create index if not exists idx_supplier_balance_snapshots_supplier_checked
  on supplier_balance_snapshots (supplier_id, checked_at desc);

alter table supplier_balance_snapshots enable row level security;

drop policy if exists "supplier_balance_snapshots_owner_read" on supplier_balance_snapshots;
create policy "supplier_balance_snapshots_owner_read"
  on supplier_balance_snapshots
  for select
  using ((auth.jwt() -> 'app_metadata' ->> 'role') = 'owner');

revoke all on table supplier_balance_snapshots from public, anon, authenticated;
grant select on table supplier_balance_snapshots to authenticated;
grant all on table supplier_balance_snapshots to service_role;

-- ---------------------------------------------------------------------------
-- redeem_discount_code
-- Locks the code, checks the rules, inserts the redemption, and increments
-- used_count in one transaction. Two checkouts cannot over-redeem.
-- service_role only.
-- ---------------------------------------------------------------------------

create or replace function redeem_discount_code(
  p_code_id uuid,
  p_customer_id uuid,
  p_order_id uuid,
  p_order_minor bigint
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  code_row discount_codes%rowtype;
  customer_uses integer;
  inserted_id uuid;
begin
  if p_order_minor is null or p_order_minor < 0 then
    return jsonb_build_object('ok', false, 'reason', 'min_order');
  end if;

  select * into code_row
  from discount_codes
  where id = p_code_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'missing');
  end if;
  if code_row.active is not true then
    return jsonb_build_object('ok', false, 'reason', 'inactive');
  end if;
  if code_row.starts_at is not null and code_row.starts_at > now() then
    return jsonb_build_object('ok', false, 'reason', 'not_started');
  end if;
  if code_row.expires_at is not null and code_row.expires_at <= now() then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  if code_row.max_uses is not null and code_row.used_count >= code_row.max_uses then
    return jsonb_build_object('ok', false, 'reason', 'max_uses');
  end if;
  if p_order_minor < code_row.min_order_minor then
    return jsonb_build_object('ok', false, 'reason', 'min_order');
  end if;

  if code_row.per_customer_limit is not null then
    select count(*) into customer_uses
    from discount_redemptions
    where code_id = p_code_id and customer_id = p_customer_id;
    if customer_uses >= code_row.per_customer_limit then
      return jsonb_build_object('ok', false, 'reason', 'per_customer');
    end if;
  end if;

  insert into discount_redemptions (code_id, customer_id, order_id)
  values (p_code_id, p_customer_id, p_order_id)
  on conflict (code_id, order_id) do nothing
  returning id into inserted_id;

  if inserted_id is null then
    return jsonb_build_object('ok', true, 'reason', 'already');
  end if;

  update discount_codes
  set used_count = used_count + 1
  where id = p_code_id;

  return jsonb_build_object('ok', true, 'reason', 'redeemed');
end;
$$;

revoke all on function redeem_discount_code(uuid, uuid, uuid, bigint) from public, anon, authenticated;
grant execute on function redeem_discount_code(uuid, uuid, uuid, bigint) to service_role;

-- ---------------------------------------------------------------------------
-- Abuse thresholds. Referral claims per day already exist from 0032.
-- These add freebie claims per day and discount redemptions per customer.
-- ---------------------------------------------------------------------------

alter table platform_settings
  add column if not exists fraud_referral_claims_per_day integer not null default 10,
  add column if not exists fraud_freebie_claims_per_day integer not null default 5,
  add column if not exists fraud_discount_redemptions_per_customer integer not null default 5;

alter table platform_settings
  drop constraint if exists platform_settings_abuse_thresholds_chk;
alter table platform_settings
  add constraint platform_settings_abuse_thresholds_chk
  check (
    fraud_referral_claims_per_day > 0
    and fraud_freebie_claims_per_day > 0
    and fraud_discount_redemptions_per_customer > 0
  );

-- ---------------------------------------------------------------------------
-- One store can lock fields differently from the platform default.
-- Null means use platform_settings.reseller_policy.
-- ---------------------------------------------------------------------------

alter table tenants
  add column if not exists reseller_policy_override jsonb;

alter table tenants
  drop constraint if exists tenants_reseller_policy_override_chk;
alter table tenants
  add constraint tenants_reseller_policy_override_chk
  check (reseller_policy_override is null or jsonb_typeof(reseller_policy_override) = 'object');

-- ---------------------------------------------------------------------------
-- store_config_versions
-- Bot Studio lists earlier saves and restores one.
-- ---------------------------------------------------------------------------

create table if not exists store_config_versions (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade,
  version integer not null,
  config jsonb not null,
  saved_by uuid references profiles(id),
  saved_at timestamptz not null default now(),
  constraint store_config_versions_version_chk check (version > 0),
  constraint store_config_versions_object_chk check (jsonb_typeof(config) = 'object')
);

-- Version list for one store, newest first.
-- Query: select version, config, saved_at from store_config_versions
--        where tenant_id is null order by version desc
--        or where tenant_id = $store order by version desc
-- Why: Bot Studio opens one store's history. The unique index also stops two
-- saves from taking the same version number.
create unique index if not exists store_config_versions_store_version_uidx
  on store_config_versions (
    (coalesce(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    version
  );

alter table store_config_versions enable row level security;

drop policy if exists "store_config_versions_owner_read" on store_config_versions;
create policy "store_config_versions_owner_read"
  on store_config_versions
  for select
  using (
    tenant_id is null
    and (auth.jwt() -> 'app_metadata' ->> 'role') = 'owner'
  );

drop policy if exists "store_config_versions_reseller_read" on store_config_versions;
create policy "store_config_versions_reseller_read"
  on store_config_versions
  for select
  using (
    tenant_id is not null
    and tenant_id in (select id from tenants where owner_user_id = auth.uid())
  );

revoke all on table store_config_versions from public, anon, authenticated;
grant select on table store_config_versions to authenticated;
grant all on table store_config_versions to service_role;
